using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpRestServer;

/// <summary>
/// MCP tool class wrapping a REST API.
/// The SDK discovers tools by scanning for [McpServerToolType] classes
/// and [McpServerTool] methods. DI parameters (like HttpClient) are
/// resolved automatically; non-DI parameters become tool inputs for the LLM.
/// </summary>
[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Get the current weather for a city.")]
    public static async Task<string> GetCurrentWeather(
        HttpClient httpClient,
        [Description("City name, e.g. 'London' or 'New York'.")] string city,
        [Description("Units: 'metric' or 'imperial'. Default: metric.")] string units = "metric")
    {
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";
        var response = await httpClient.GetAsync(url);
        response.EnsureSuccessStatusCode();

        using var doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync());
        var current = doc.RootElement.GetProperty("current_condition")[0];

        var tempKey = units == "imperial" ? "temp_F" : "temp_C";
        var tempUnit = units == "imperial" ? "°F" : "°C";

        var temp = current.GetProperty(tempKey).GetString();
        var desc = current.GetProperty("weatherDesc")[0].GetProperty("value").GetString();
        var humidity = current.GetProperty("humidity").GetString();
        var windMph = current.GetProperty("windspeedMiles").GetString();

        return $"Weather in {city}: {desc}, {temp}{tempUnit}, " +
               $"Humidity: {humidity}%, Wind: {windMph} mph";
    }

    [McpServerTool, Description("Get a multi-day weather forecast for a city.")]
    public static async Task<string> GetForecast(
        HttpClient httpClient,
        [Description("City name.")] string city,
        [Description("Number of forecast days (1-3). Default: 3.")] int days = 3)
    {
        days = Math.Clamp(days, 1, 3);
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";
        var response = await httpClient.GetAsync(url);
        response.EnsureSuccessStatusCode();

        using var doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync());
        var forecast = doc.RootElement.GetProperty("weather");

        var lines = new List<string> { $"Forecast for {city}:" };
        foreach (var day in forecast.EnumerateArray().Take(days))
        {
            var date = day.GetProperty("date").GetString();
            var maxC = day.GetProperty("maxtempC").GetString();
            var minC = day.GetProperty("mintempC").GetString();
            var desc = day.GetProperty("hourly")[4] // midday
                .GetProperty("weatherDesc")[0]
                .GetProperty("value").GetString();
            lines.Add($"  {date}: {desc}, {minC}-{maxC}°C");
        }

        return string.Join("\n", lines);
    }
}

